const mock=await startMock();
const browser=await chromium.launch({executablePath:process.env.ZFSM_CHROME,headless:true});
const results=[],issues=[],measurements=[],requests=new Set();let context,page;
const project=lab+'/project',snap=project+'@base';
const names={snapshotdataset:'Take Snapshot',renamedataset:'Rename dataset',editdatasetproperty:'Edit Dataset',adddirectortlisting:'Add Directory Listing',removedirectorylisting:'Remove Directory Listing',promotedataset:'Promote clone',lockdataset:'Lock dataset',unlockdataset:'Unlock dataset',destroydataset:'Destroy dataset',movedirectory:'Move / Rename',deletedirectory:'Delete directory',convertdirectory:'Convert to dataset'};
function mutationCalls(cmd){return mock.model.calls.filter(c=>c.cmd===cmd);}
async function savedMockDownload(event){const download=await event;assert.equal(await download.failure(),null,'Attachment must finish, not only emit headers');const path=await download.path();assert.ok(path,'Browser must save the attachment');assert.equal(await readFile(path,'utf8'),'SIMULATED DOWNLOAD: no server file content');}
async function fresh({width=1280,mode}={}){
    if(context)await context.close();mock.reset();
    if(['0','30'].includes(process.env.ZFSM_REFRESH_INTERVAL))assert.equal(mock.model.config.refresh_interval,Number(process.env.ZFSM_REFRESH_INTERVAL),'Each scenario starts with the requested refresh profile');
    mode?.(mock.model);
    context=await browser.newContext({viewport:{width,height:960},acceptDownloads:true});page=await context.newPage();
    page.setDefaultTimeout(5000);
    await context.route('**/*',route=>route.request().url().startsWith(mock.url)?route.continue():route.abort());
    page.on('pageerror',e=>issues.push({test:results.length+1,type:'pageerror',message:e.message}));
    context.on('request',r=>{if(r.method()==='POST'){const cmd=new URLSearchParams(r.postData()).get('cmd');if(cmd)requests.add(cmd);}});
    await page.goto(mock.url);await page.locator('[data-node="'+project+'"]').waitFor();assert.equal(await page.locator('.zfsm-brand strong').textContent(),'ZFS Director');assert.match(await page.title(),/^ZFS Director/);
    if(process.env.ZFSM_INJECT_PAGE_ERROR==='1')await page.evaluate(()=>{queueMicrotask(()=>{throw Error('acceptance synthetic pageerror');});});
}
async function capture(name){assert.doesNotMatch(await page.locator('body').innerText(),/ZFS[ _-]+Master/i);await page.screenshot({path:output+'/screenshots/'+name+'.png',fullPage:false});}
async function scenario(name,fn){
    if(process.env.ZFSM_CASE&&!name.includes(process.env.ZFSM_CASE))return;
    const start=Date.now();try{await fn();results.push({name,status:'PASS',ms:Date.now()-start});console.log('PASS '+name);}
    catch(error){results.push({name,status:'FAIL',message:error.message,ms:Date.now()-start});console.log('FAIL '+name+': '+error.message.split('\n')[0]);if(page&&!page.isClosed())await capture('failure-'+results.length).catch(()=>{});}
}
async function select(name=project,tab='Actions'){if(await page.locator('.zfsm-action-dialog[open]').count())await page.getByRole('button',{name:'Close action',exact:true}).click();await page.locator('[data-node="'+name+'"]').click();await page.getByRole('navigation',{name:'Workspace tabs',exact:true}).getByRole('button',{name:tab,exact:true}).click();}
async function action(cmd,name=project){await select(name);await page.getByRole('button',{name:names[cmd],exact:true}).click();await page.locator('.zfsm-form').waitFor();}
async function confirm(cmd,{preview=false}={}){
    const form=page.locator('.zfsm-form');
    if(preview||cmd==='destroysnapshot'){await form.locator('[data-preview]').click();await form.locator('.zfsm-preview pre, .zfsm-preview strong').first().waitFor();}
    for(const key of ['acknowledge','offline_confirmed'])if(await form.locator('[name="'+key+'"]').count())await form.locator('[name="'+key+'"]').check();
    const before=mutationCalls(cmd).length;
    await form.locator('button[type="submit"]').click();await form.locator('[data-confirm-operation]').waitFor();
    assert.equal(mutationCalls(cmd).length,before,'No mutation before explicit confirmation');
    const response=page.waitForResponse(r=>r.url()===mock.url+'/mock/admin'&&new URLSearchParams(r.request().postData()).get('cmd')===cmd);
    await form.locator('[data-confirm-operation]').click();await response;
    assert.equal(mutationCalls(cmd).length,before+1,'Exactly one confirmed mutation');
    assert.equal(mutationCalls(cmd).at(-1).csrf_token,'fixture-token');
}
async function snapshotAction(cmd,name=snap){
    await select(name.split('@')[0],'Snapshots');
    const row=page.locator('tr').filter({has:page.getByText(name,{exact:true})});
    await row.getByRole('button',{name:'Operations',exact:true}).click();
    await page.locator('[data-snapshot-action="'+cmd+'"]').filter({visible:true}).click();
}
